test('customer discount is applied once (under 10 lines)', () => {
  // 1000 * (1 - 0.1) = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10000 * (1 - 0.1) = 9000, then 9000 * (1 - 0.05) = 8550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('9 lines get the customer discount only (no bulk discount)', () => {
  // 9000 * (1 - 0.1) = 8100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// Issue #12: totals with a discount rate of 0 must stay as they were before the fix.
test('totals with discount rate 0 are unchanged', () => {
  assert.equal(total(lines(10, 1000), 0), 9500); // bulk only: 10000 * 0.95
  assert.equal(total(lines(9, 1000), 0), 9000); // no discount at all
  assert.equal(total(lines(10, 333), 0), 3164); // 3330 * 0.95 = 3163.5, rounded
  assert.equal(total(lines(10, 1000)), total(lines(10, 1000), 0)); // default rate is 0
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
